/// <summary>
/// The Document handler for the online validation aspect of the mobile WMS.
/// </summary>
[TFMValidationDocumentType(methodStr(MobOnlineValidator,GetSerialNumberInformation) , methodStr(MobOnlineValidator,GetSerialNumberInformation)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,LineSelectionFromBarcode) , methodStr(MobOnlineValidator,LineSelectionFromBarcode)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,ValidateBatchNumber) , methodStr(MobOnlineValidator,ValidateBatchNumber)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,LocationValidation) , methodStr(MobOnlineValidator,LocationValidation)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,quantityValidation) , methodStr(MobOnlineValidator,quantityValidation)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,toteValidation) , methodStr(MobOnlineValidator,toteValidation)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,validateSerialNumberReceipt), methodStr(MobOnlineValidator,validateSerialNumberReceipt)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,toteTypeValidation) , methodStr(MobOnlineValidator,toteTypeValidation)),
    TFMValidationDocumentType(methodStr(MobOnlineValidator,LicensePlateValidation), methodStr(MobOnlineValidator,LicensePlateValidation))
    ]
class MobOnlineValidator extends TFMDocumentHandler
{    

    #define.AttributeBin('bin')
    MobRequestValidationElement			validationRequest;

    TFMValueInteractionPermission		valueInteractionPermissionBatch;
    NoYes								updateBatchQuantity;
    TFMValueInteractionPermission		valueInteractionPermissionSerial;
    NoYes								updateSerialQuantity;
    NoYes                               promptForContainerType;



}

